    "body": "<div class=\"page\" style=\"background:var(--bg-dark)\">\n\n    <!-- Header -->\n    <header class=\"header\">\n        <a href=\"landing.html\" class=\"btn btn-ghost btn-sm\">\n            <img src=\"assets/ui/exit cross.png\" class=\"btn-icon-img\" alt=\"\"> Kingdom Gate\n        </a>\n        <div class=\"header-title\">KNIGHT'S HALL</div>\n        <div class=\"header-actions\">\n            <div class=\"wallet-pill\" id=\"walletWidgetMenu\">\n                <span id=\"menuGold\">0 DNG</span>\n            </div>\n        </div>\n    </header>\n\n    <!-- Two-panel layout -->\n    <div style=\"flex:1;display:flex;overflow:hidden\">\n\n        <!-- LEFT: Actions -->\n        <aside class=\"side-panel\" style=\"width:300px\">\n            <div class=\"side-panel-header\">\n                <img src=\"assets/ui/sword.png\" class=\"panel-header-icon\" alt=\"\">\n                Embark on Quest\n            </div>\n            <div class=\"side-panel-body\" style=\"display:flex;flex-direction:column;gap:10px\">\n\n                <button class=\"btn btn-primary btn-md w-full\" id=\"playGameBtn\" style=\"justify-content:flex-start;gap:10px\">\n                    <img src=\"assets/ui/sword.png\" class=\"btn-icon-img\" alt=\"\">\n                    <div style=\"text-align:left\">\n                        <div>Enter Dungeon</div>\n                        <div style=\"font-size:10px;font-weight:400;color:var(--text-muted);letter-spacing:0.5px\">Deploy selected knights</div>\n                    </div>\n                </button>\n\n                <button class=\"btn btn-secondary btn-md w-full\" id=\"backMenuBtn\" style=\"justify-content:flex-start;gap:10px\">\n                    <img src=\"assets/ui/castle.png\" class=\"btn-icon-img\" alt=\"\">\n                    <div>Return to Gate</div>\n                </button>\n\n                <div style=\"border-top:1px solid var(--border-base);margin:6px 0\"></div>\n\n                <div style=\"display:flex;gap:8px\">\n                    <button class=\"btn btn-secondary btn-sm\" style=\"flex:1\" id=\"selectAllBtn\">\n                        <img src=\"assets/ui/right tick.png\" class=\"btn-icon-img\" alt=\"\"> Select All\n                    </button>\n                    <button class=\"btn btn-danger btn-sm\" style=\"flex:1\" id=\"deselectAllBtn\">\n                        <img src=\"assets/ui/exit cross.png\" class=\"btn-icon-img\" alt=\"\"> Clear\n                    </button>\n                </div>\n\n                <div class=\"stat-row\" style=\"margin-top:4px\">\n                    <span class=\"stat-label\">Selected Knights</span>\n                    <span class=\"stat-value stat-value-gold\"><span id=\"activeTroopsCount\">0</span> / 15</span>\n                </div>\n            </div>\n        </aside>\n\n        <!-- RIGHT: Knight Roster -->\n        <main class=\"side-panel hall-bg hall-bg-knight\" style=\"flex:1;border-right:none\">\n            <div class=\"side-panel-header\" style=\"justify-content:space-between\">\n                <div style=\"display:flex;align-items:center;gap:8px\">\n                    <img src=\"assets/ui/shield.png\" class=\"panel-header-icon\" alt=\"\">\n                    Knight Roster\n                </div>\n                <div style=\"display:flex;gap:8px\">\n                    <select class=\"select\" id=\"sortFilter\" style=\"font-size:11px;padding:4px 24px 4px 8px\">\n                        <option value=\"id\">Sort: ID</option>\n                        <option value=\"rarity\">Rarity</option>\n                        <option value=\"power\">Power</option>\n                        <option value=\"stamina\">Stamina</option>\n                    </select>\n                    <select class=\"select\" id=\"rarityFilter\" style=\"font-size:11px;padding:4px 24px 4px 8px\">\n                        <option value=\"all\">All</option>\n                        <option value=\"LEGENDARY\">Legendary</option>\n                        <option value=\"EPIC\">Epic</option>\n                        <option value=\"RARE\">Rare</option>\n                        <option value=\"UNCOMMON\">Uncommon</option>\n                        <option value=\"COMMON\">Common</option>\n                    </select>\n                </div>\n            </div>\n            <div class=\"side-panel-body\">\n                <div class=\"stat-row\">\n                    <span class=\"stat-label\">Total Knights</span>\n                    <span class=\"stat-value\" id=\"totalKnightsCount\">0</span>\n                </div>\n                <div id=\"knightRoster\">\n                    <p style=\"color:var(--text-muted);font-style:italic;text-align:center;padding:40px 20px\">\n                        No knights recruited yet. Visit the Summoning Chamber to forge your first knight.\n                    </p>\n                </div>\n            </div>\n        </main>\n    </div>\n\n    <!-- Footer -->\n    <footer style=\"height:36px;display:flex;align-items:center;justify-content:center;background:var(--bg-dark);border-top:1px solid var(--border-base);flex-shrink:0\">\n        <span style=\"font-size:11px;color:var(--text-muted);letter-spacing:0.5px\">\n            Select up to 15 knights and deploy them into the dungeons\n        </span>\n    </footer>\n</div>\n\n<!-- Knight Detail Modal -->\n<div id=\"knightModal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal\">\n        <div class=\"modal-title\" id=\"modalKnightName\">Knight #1</div>\n        <div class=\"modal-stats\" id=\"modalRarity\" style=\"color:var(--text-muted);font-size:13px;margin-bottom:16px\">Common</div>\n        <div class=\"modal-stats\">\n            <p><strong>Power</strong> <span id=\"modalPower\">10</span></p>\n            <p><strong>Speed</strong> <span id=\"modalSpeed\">1.0</span></p>\n            <p><strong>Max Stamina</strong> <span id=\"modalMaxStamina\">100</span></p>\n            <p><strong>Status</strong> <span id=\"modalStatus\">Ready</span></p>\n            <p><strong>Total Earned</strong> <span id=\"modalEarned\">0</span></p>\n        </div>\n        <div style=\"margin-bottom:16px\">\n            <div style=\"display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px\">\n                <span style=\"color:var(--text-muted)\">Stamina</span>\n                <span id=\"modalStaminaText\" style=\"color:var(--text-secondary)\">100 / 100</span>\n            </div>\n            <div class=\"stat-bar-track\">\n                <div class=\"stat-bar-fill\" id=\"modalStaminaBar\" style=\"width:100%\"></div>\n            </div>\n        </div>\n        <div class=\"modal-actions\">\n            <button class=\"btn btn-primary btn-md\" id=\"modalSelectBtn\" style=\"flex:1\">Add to Squad</button>\n            <button class=\"btn btn-secondary btn-md\" id=\"modalCloseBtn\" style=\"flex:1\">Close</button>\n        </div>\n    </div>\n</div>",
