    "body": "<div class=\"page\">\n\n    <!-- ============ HEADER ============ -->\n    <header class=\"header\">\n        <div class=\"header-brand\">\n            <a href=\"menu.html\" class=\"btn btn-ghost btn-sm\" style=\"gap:6px\">\n                <img src=\"assets/ui/sword.png\" class=\"btn-icon-img\" alt=\"\">\n                <span>Knights</span>\n            </a>\n        </div>\n        <div class=\"header-title\">DUNGEON KNIGHTS</div>\n        <div class=\"header-actions\">\n            <div class=\"wallet-pill\" id=\"walletWidgetGame\">\n                <span id=\"walletAddressDisplay\" style=\"display:none\"></span>\n                <span id=\"headerDngBalance\">0 DNG</span>\n                <button id=\"disconnectBtn\" class=\"btn btn-disconnect\" style=\"display:none\">Disconnect</button>\n            </div>\n        </div>\n    </header>\n\n    <!-- ============ MAIN ============ -->\n    <div class=\"game-main\">\n\n        <!-- LEFT PANEL: Active Squad -->\n        <aside class=\"side-panel\">\n            <div class=\"side-panel-header\">\n                <img src=\"assets/ui/sword.png\" class=\"panel-header-icon\" alt=\"\">\n                Active Squad\n            </div>\n            <div class=\"side-panel-body\">\n                <div class=\"knight-card\" id=\"squadList\">\n                    <!-- JS-populated -->\n                </div>\n            </div>\n        </aside>\n\n        <!-- CENTER: Canvas + Video -->\n        <div class=\"canvas-area\">\n            <video id=\"dungeonBackground\" autoplay loop muted playsinline class=\"dungeon-video-bg\">\n                <!-- No src here on purpose: the engine sets the chosen dungeon's video in\n                     switchDungeonVideo(), and a hard-coded crypts source meant the crypts\n                     map painted (and downloaded) before the real one took over. -->\n                <source type=\"video/mp4\">\n            </video>\n            <canvas id=\"gameCanvas\" width=\"1140\" height=\"600\"></canvas>\n        </div>\n\n        <!-- RIGHT PANEL: Info -->\n        <aside class=\"side-panel right\">\n            <!-- Wallet / Stats -->\n            <div class=\"side-panel-header\">\n                <img src=\"assets/ui/shield.png\" class=\"panel-header-icon\" alt=\"\">\n                Status\n            </div>\n            <div class=\"side-panel-body\">\n                <div class=\"stat-row\">\n                    <span class=\"stat-label\">Wallet</span>\n                    <span class=\"stat-value stat-value-gold\" id=\"ownerMark\">0 DNG</span>\n                </div>\n                <div class=\"stat-row\">\n                    <span class=\"stat-label\">Total Claimed</span>\n                    <span class=\"stat-value\" id=\"resourceAmount\">0</span>\n                </div>\n            </div>\n\n            <!-- Chest Display -->\n            <div class=\"chest-display\">\n                <img id=\"chestImage\" class=\"chest-display-img\" alt=\"Chest\">\n            </div>\n\n            <!-- Rewards -->\n            <div class=\"side-panel-header\" style=\"border-top:1px solid var(--border-base)\">\n                <img src=\"assets/ui/right tick.png\" class=\"panel-header-icon\" alt=\"\">\n                Unclaimed\n            </div>\n            <div class=\"side-panel-body rewards-block\">\n                <div class=\"rewards-total\" id=\"rewardsTotal\">0.00 DNG</div>\n                <div class=\"rewards-meta\" id=\"rewardsCompletions\">Completions: 0</div>\n                <div style=\"display:flex;flex-direction:column;gap:8px;margin-top:12px\">\n                    <button class=\"btn btn-primary btn-md w-full\" id=\"claimAllBtn\">\n                        <img src=\"assets/ui/right tick.png\" class=\"btn-icon-img\" alt=\"\"> Claim All\n                    </button>\n                    <button class=\"btn btn-secondary btn-md w-full\" id=\"viewHistoryBtn\">History</button>\n                    <button class=\"btn btn-secondary btn-md w-full\" id=\"leaderboardBtn\">Leaderboard</button>\n                </div>\n            </div>\n        </aside>\n    </div>\n\n    <!-- ============ BOTTOM BAR ============ -->\n    <footer class=\"control-bar\">\n        <div class=\"control-group\">\n            <button class=\"btn btn-primary btn-md\" id=\"deployBtn\">\n                <img src=\"assets/ui/sword.png\" class=\"btn-icon-img\" alt=\"\"> Deploy\n            </button>\n            <button class=\"btn btn-danger btn-md\" id=\"recallBtn\">\n                <img src=\"assets/ui/exit cross.png\" class=\"btn-icon-img\" alt=\"\"> Recall\n            </button>\n            <button class=\"btn btn-secondary btn-md\" id=\"menuBtn\">\n                <img src=\"assets/ui/castle.png\" class=\"btn-icon-img\" alt=\"\"> Menu\n            </button>\n        </div>\n\n        <div class=\"control-stats\">\n            <div class=\"control-stat\">DNG/min: <strong id=\"dngRate\">0</strong></div>\n            <div class=\"control-stat\">Active: <strong id=\"activeKnights\">0/15</strong></div>\n            <div class=\"control-stat\">Loot: <strong id=\"activeLoot\">0</strong></div>\n            <div class=\"control-stat\">Est. Time: <strong id=\"estimatedTime\">--</strong></div>\n        </div>\n\n        <div class=\"control-group\">\n            <button class=\"btn btn-secondary btn-md\" id=\"statsBtn\">\n                <img src=\"assets/ui/sword.png\" class=\"btn-icon-img\" alt=\"\"> Stats\n            </button>\n        </div>\n    </footer>\n\n    <!-- Toast notification -->\n    <div class=\"toast\" id=\"parchmentNote\">\n        <div class=\"toast-title\">Welcome Adventurer</div>\n        <div class=\"toast-body\">Press 'H' for shortcuts<br>Deploy knights to begin!</div>\n    </div>\n</div>\n\n<!-- ============ MAP LOADING GATE ============ -->\n<!-- Painted from the first frame, so the placeholder map never shows, and taken down\n     by loading-gate.js once the chosen dungeon's art has actually arrived. Arya stands\n     on it (z-index 2200) saying hold on. -->\n<div id=\"mapLoadingGate\" role=\"status\" aria-live=\"polite\">\n    <div class=\"map-gate-title\">Entering <span id=\"mapGateName\">your dungeon</span></div>\n    <div class=\"map-gate-sub\">The gate keeper is holding the door</div>\n    <div class=\"map-gate-track\"><div class=\"map-gate-bar\" id=\"mapGateBar\"></div></div>\n    <div class=\"map-gate-label\">\n        <span id=\"mapGateLabel\">Unrolling the map…</span>\n        <span class=\"map-gate-count\" id=\"mapGateCount\"></span>\n    </div>\n</div>\n\n<!-- ============ MODALS ============ -->\n<div id=\"completionModal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal\">\n        <div class=\"modal-title\">Dungeon Cleared</div>\n        <div class=\"modal-stats\">\n            <p><strong>Dungeon</strong> <span id=\"completedDungeon\">-</span></p>\n            <p><strong>Gold Earned</strong> <span id=\"completionGold\">0</span> DNG</p>\n            <p><strong>Time</strong> <span id=\"completionTime\">0:00</span></p>\n        </div>\n        <div class=\"modal-actions\">\n            <button class=\"btn btn-primary btn-md\" id=\"nextDungeonBtn\" style=\"flex:1\">Next Dungeon</button>\n            <button class=\"btn btn-secondary btn-md\" id=\"replayDungeonBtn\" style=\"flex:1\">Replay</button>\n        </div>\n    </div>\n</div>\n\n<div id=\"shortcutsOverlay\" class=\"modal-backdrop hidden\">\n    <div class=\"modal\">\n        <div class=\"modal-title\">Shortcuts</div>\n        <div style=\"margin-bottom:24px;color:var(--text-secondary);font-size:14px;line-height:2\">\n            <p><strong style=\"color:var(--text-primary);width:80px;display:inline-block\">Space</strong> Deploy Knights</p>\n            <p><strong style=\"color:var(--text-primary);width:80px;display:inline-block\">Esc</strong> Recall Knights</p>\n            <p><strong style=\"color:var(--text-primary);width:80px;display:inline-block\">H</strong> Toggle Help</p>\n        </div>\n        <button class=\"btn btn-secondary btn-md w-full\" id=\"shortcutsClose\">Close</button>\n    </div>\n</div>\n\n<!-- ============ SCRIPTS ============ -->",
